from collections import Counter
def sym_fix(g):
    n,m=len(g),len(g[0])
    out=[]
    for i in range(n):
        row=[]
        for j in range(m):
            vals=[g[i][j],g[i][m-1-j],g[n-1-i][j],g[n-1-i][m-1-j]]
            if len(set(vals))==1: row.append(g[i][j])
            else:
                others=vals[1:]
                row.append(Counter(others).most_common(1)[0][0])
        out.append(row)
    return out
