def orbit(g,i,j):
    n,m=len(g),len(g[0])
    idx={(i,j),(i,m-1-j),(n-1-i,j),(n-1-i,m-1-j),(j,i),(j,m-1-i),(n-1-j,i),(n-1-j,m-1-i)}
    return [g[a][b] for a,b in idx]
def iterate(g, rounds=30):
    g=[r[:] for r in g]
    for _ in range(rounds):
        ng=[r[:] for r in g]
        changed=False
        for i in range(len(g)):
            for j in range(len(g[0])):
                o=orbit(g,i,j)
                if len(set(o))>1:
                    v=Counter(o).most_common(1)[0][0]
                    if v!=ng[i][j]: ng[i][j]=v; changed=True
        g=ng
        if not changed: break
    return g
